+.footer-col a{display:block; padding:6px 0; color:var(--muted);}
+.footer-col a:hover{color:var(--text);}
+.footer-bottom{padding:14px 0; display:flex; justify-content:space-between; gap:12px; flex-wrap:wrap; color:var(--muted-2); font-size:13px;}
